175	static FilterPropagateResult CheckZonemapAgainstConstants(const BaseStatistics &stats, ExpressionType comparison_type,
176	                                                          array_ptr<const Value> values) {
177		D_ASSERT(values.size() > 0);
178		switch (values[0].type().InternalType()) {
179		case PhysicalType::BOOL:
180		case PhysicalType::UINT8:
181		case PhysicalType::UINT16:
182		case PhysicalType::UINT32:
183		case PhysicalType::UINT64:
184		case PhysicalType::UINT128:
185		case PhysicalType::INT8:
186		case PhysicalType::INT16:
187		case PhysicalType::INT32:
188		case PhysicalType::INT64:
189		case PhysicalType::INT128:
190		case PhysicalType::FLOAT:
191		case PhysicalType::DOUBLE:
192			return NumericStats::CheckZonemap(stats, comparison_type, values);
193		case PhysicalType::VARCHAR:
194			if (stats.GetStatsType() == StatisticsType::STRING_STATS) {
195				return StringStats::CheckZonemap(stats, comparison_type, values);
196			}
197			return FilterPropagateResult::NO_PRUNING_POSSIBLE;
198		default:
199			return FilterPropagateResult::NO_PRUNING_POSSIBLE;
200		}
201	}
202	
203	static optional_ptr<const BaseStatistics> TryGetFilterStats(optional_ptr<ClientContext> context_p,
204	                                                            const Expression &expr, const BaseStatistics &stats,
205	                                                            vector<unique_ptr<BaseStatistics>> &owned_stats) {
206		switch (expr.GetExpressionClass()) {
207		case ExpressionClass::BOUND_REF:
208			return &stats;
209		case ExpressionClass::BOUND_CONSTANT: {
210			auto &constant = expr.Cast<BoundConstantExpression>().GetValue();
211			owned_stats.push_back(BaseStatistics::FromConstant(constant).ToUnique());
212			return owned_stats.back().get();
213		}
214		case ExpressionClass::BOUND_CAST: {
215			auto &cast_expr = expr.Cast<BoundCastExpression>();
216			auto child_stats = TryGetFilterStats(context_p, cast_expr.Child(), stats, owned_stats);
217			if (!child_stats) {
218				return nullptr;
219			}
220			auto cast_stats = StatisticsPropagator::TryPropagateCast(*child_stats, cast_expr.Child().GetReturnType(),
221			                                                         cast_expr.GetReturnType());
222			if (!cast_stats) {
223				return nullptr;
224			}
225			if (cast_expr.IsTryCast()) {
226				cast_stats->Set(StatsInfo::CAN_HAVE_NULL_VALUES);
227			}
228			owned_stats.push_back(std::move(cast_stats));
229			return owned_stats.back().get();
230		}
231		case ExpressionClass::BOUND_FUNCTION: {
232			auto &func = expr.Cast<BoundFunctionExpression>();
233	
234			if (!context_p) {
235				// Since statistics callback need context, so this path is the fallback
236				idx_t child_idx;
237				if (TryGetStructExtractChildIndex(func, child_idx) && !func.GetChildren().empty()) {
238					auto child_stats = TryGetFilterStats(context_p, *func.GetChildren()[0], stats, owned_stats);
239					if (!child_stats || child_stats->GetType().id() != LogicalTypeId::STRUCT) {
240						return nullptr;
241					}
242					owned_stats.push_back(StructStats::GetChildStats(*child_stats, child_idx).ToUnique());
243					return owned_stats.back().get();
244				}
245				return nullptr;
246			}
247	
248			if (func.Function().HasStatisticsCallback()) {
249				vector<BaseStatistics> child_stats;
250				child_stats.reserve(func.GetChildren().size());
251				for (auto &child_expr : func.GetChildren()) {
252					auto child_stat = TryGetFilterStats(context_p, *child_expr, stats, owned_stats);
253					if (!child_stat) {
254						return nullptr;
255					}
256					child_stats.push_back(child_stat->Copy());
257				}
258	
259				// Use copy to avoid expression rewritten
260				auto expr_copy = func.Copy();
261				auto &func_copy = expr_copy->Cast<BoundFunctionExpression>();
262				FunctionStatisticsInput input(func_copy, func_copy.BindInfo(), child_stats, &expr_copy);
263				owned_stats.push_back(func.Function().GetStatisticsCallback()(*context_p, input));
264				return owned_stats.back().get();
265			}
266	
267			// No custom callback: fall back to the declared monotonicity (ArgProperties) and derive output
268			// bounds by evaluating the function at the corners of each argument's range. This lets a
269			// f(col) OP const filter prune row groups via the zonemap of the base column.
270			if (func.Function().HasArgProperties()) {
271				vector<BaseStatistics> child_stats;
272				child_stats.reserve(func.GetChildren().size());
273				for (auto &child_expr : func.GetChildren()) {
274					auto child_stat = TryGetFilterStats(context_p, *child_expr, stats, owned_stats);
275					child_stats.push_back(child_stat ? child_stat->Copy()
276					                                 : BaseStatistics::CreateUnknown(child_expr->GetReturnType()));
277				}
278				auto derived = StatisticsPropagator::PropagateMonotoneBounds(*context_p, func, child_stats);
279				if (derived) {
280					owned_stats.push_back(std::move(derived));
281					return owned_stats.back().get();
282				}
283			}
284	
285			return nullptr;
286		}
287		default:
288			return nullptr;
289		}
290	}
