292	static bool TryGetVariantComparisonStatsType(const LogicalType &typed_type, const LogicalType &constant_type,
293	                                             LogicalType &comparison_type) {
294		if (typed_type == constant_type) {
295			comparison_type = typed_type;
296			return true;
297		}
298		if (!typed_type.IsIntegral() || !constant_type.IsIntegral()) {
299			return false;
300		}
301		if (!LogicalType::DefaultTryGetMaxLogicalTypeUnchecked(typed_type, constant_type, comparison_type)) {
302			return false;
303		}
304		return comparison_type.IsIntegral();
305	}
306	
307	static optional_ptr<const BaseStatistics>
308	TryPrepareVariantComparisonStats(const BaseStatistics &stats, Value &constant,
309	                                 vector<unique_ptr<BaseStatistics>> &owned_stats) {
310		if (stats.GetType().id() != LogicalTypeId::VARIANT) {
311			return constant.type().id() == LogicalTypeId::VARIANT ? nullptr : &stats;
312		}
313		if (!VariantStats::IsShredded(stats)) {
314			return nullptr;
315		}
316		auto &shredded_stats = VariantStats::GetShreddedStats(stats);
317		if (!VariantShreddedStats::IsFullyShredded(shredded_stats)) {
318			return nullptr;
319		}
320		auto &typed_stats = VariantStats::GetTypedStats(shredded_stats);
321		auto &typed_type = typed_stats.GetType();
322		if (typed_type.IsNested() || typed_type.id() == LogicalTypeId::VARIANT) {
323			return nullptr;
324		}
325	
326		if (constant.type().id() == LogicalTypeId::VARIANT) {
327			constant = VariantValue::GetValue(constant);
328		}
329		if (constant.IsNull()) {
330			return nullptr;
331		}
332	
333		LogicalType comparison_type;
334		if (!TryGetVariantComparisonStatsType(typed_type, constant.type(), comparison_type)) {
