14	bool PrefixFunction(const string_t &str, const string_t &pattern) {
15		auto str_length = str.GetSize();
16		auto patt_length = pattern.GetSize();
17		if (patt_length > str_length) {
18			return false;
19		}
20		if (patt_length <= string_t::PREFIX_LENGTH) {
21			// short prefix
22			if (patt_length == 0) {
23				// length = 0, return true
24				return true;
25			}
26	
27			// prefix early out
28			const char *str_pref = str.GetPrefix();
29			const char *patt_pref = pattern.GetPrefix();
30			for (idx_t i = 0; i < patt_length; ++i) {
31				if (str_pref[i] != patt_pref[i]) {
32					return false;
33				}
34			}
35			return true;
36		} else {
37			// prefix early out
38			const char *str_pref = str.GetPrefix();
39			const char *patt_pref = pattern.GetPrefix();
40			for (idx_t i = 0; i < string_t::PREFIX_LENGTH; ++i) {
41				if (str_pref[i] != patt_pref[i]) {
42					// early out
43					return false;
44				}
45			}
46			// compare the rest of the prefix
47			const char *str_data = str.GetData();
48			const char *patt_data = pattern.GetData();
49			D_ASSERT(patt_length <= str_length);
50			for (idx_t i = string_t::PREFIX_LENGTH; i < patt_length; ++i) {
51				if (str_data[i] != patt_data[i]) {
52					return false;
53				}
54			}
55			return true;
56		}
57	}
58	
59	struct PrefixOperator {
60		template <class TA, class TB, class TR>
61		static inline TR Operation(TA left, TB right) {
62			return PrefixFunction(left, right);
63		}
64	};
