66	// Update the prefix to be the next string of the given one, which is with less or equal length to the given prefix
67	bool FindNextPrefix(string &prefix) {
68		for (idx_t idx = prefix.size(); idx > 0; idx--) {
69			auto c = static_cast<uint8_t>(prefix[idx - 1]);
70			if (c == 0xFF) {
71				continue;
72			}
73			prefix[idx - 1] = static_cast<char>(c + 1);
74			prefix.resize(idx);
75			return true;
76		}
77		return false;
78	}
