80	FilterPropagateResult PrefixFilterPrune(const FunctionStatisticsPruneInput &input) {
81		auto &children = input.function.GetChildren();
82	
83		// First check whether it's possible to prune completely.
84		if (children.size() != 2 || children[1]->GetExpressionType() != ExpressionType::VALUE_CONSTANT) {
85			return FilterPropagateResult::NO_PRUNING_POSSIBLE;
86		}
87	
88		auto column_stats = input.ChildStats(0);
89		if (!column_stats || column_stats->GetStatsType() != StatisticsType::STRING_STATS) {
90			return FilterPropagateResult::NO_PRUNING_POSSIBLE;
91		}
92		// If all rows are null, always false
93		if (!column_stats->CanHaveNoNull()) {
94			return FilterPropagateResult::FILTER_ALWAYS_FALSE;
95		}
96		// If the constant is null, always false
97		auto &constant = children[1]->Cast<BoundConstantExpression>().GetValue();
98		if (constant.IsNull()) {
99			return FilterPropagateResult::FILTER_ALWAYS_FALSE;
100		}
101		// Handle empty prefix
102		auto prefix = StringValue::Get(constant);
103		if (prefix.empty()) {
104			return column_stats->CanHaveNull() ? FilterPropagateResult::NO_PRUNING_POSSIBLE
105			                                   : FilterPropagateResult::FILTER_ALWAYS_TRUE;
106		}
107	
108		// Then check row group pruning with string stats min/max.
109		if (StringStats::HasMaxStringLength(*column_stats) && StringStats::MaxStringLength(*column_stats) < prefix.size()) {
110			return FilterPropagateResult::FILTER_ALWAYS_FALSE;
111		}
112		if (!StringStats::HasMinMax(*column_stats)) {
113			return FilterPropagateResult::NO_PRUNING_POSSIBLE;
114		}
115	
116		const auto min = StringStats::Min(*column_stats);
117		const auto max = StringStats::Max(*column_stats);
118	
119		// prefix > max, always false
120		if (StringStats::CompareStringStats(string_t(prefix.c_str(), prefix.size()), string_t(max.c_str(), max.size()),
121		                                    StringStats::GetMaxType(*column_stats)) > 0) {
122			return FilterPropagateResult::FILTER_ALWAYS_FALSE;
123		}
124	
125		// next(prefix) <= min, always false
126		auto upper_bound = prefix;
127		if (FindNextPrefix(upper_bound)) {
128			const auto min_compare =
129			    StringStats::CompareStringStats(string_t(upper_bound.c_str(), upper_bound.size()),
130			                                    string_t(min.c_str(), min.size()), StringStats::GetMinType(*column_stats));
131			if (min_compare < 0) {
132				return FilterPropagateResult::FILTER_ALWAYS_FALSE;
133			}
134			if (min_compare == 0 && StringStats::GetMinType(*column_stats) == StringStatsType::EXACT_STATS) {
135				return FilterPropagateResult::FILTER_ALWAYS_FALSE;
136			}
137		}
